// Independent Lands Department check point, not a value generated by this code.
const assert=require('node:assert/strict');
const geo=require('./static/geo.js');
const source={x:832591.320,y:820359.389};
const point=geo.toWgs84(source.x,source.y);
assert.ok(Math.abs(point.latitude-22.322244329)<1e-8,'LandsD latitude benchmark');
assert.ok(Math.abs(point.longitude-114.141187898)<1e-8,'LandsD longitude benchmark');
for(const xy of [[null,820000],[undefined,820000],[NaN,820000],[0,0],[114.18,22.25],[Infinity,820000]]){
  assert.throws(()=>geo.toWgs84(...xy));
}
const url=new URL(geo.googleMapsUrl(point));
assert.equal(url.hostname,'www.google.com');
assert.equal(url.searchParams.get('api'),'1');
assert.equal(url.searchParams.get('query'),'22.3222443,114.1411879');
const satellite=new URL(geo.googleEmbedUrl(point,true));
assert.equal(satellite.searchParams.get('q'),'22.3222443,114.1411879');
assert.equal(satellite.searchParams.get('t'),'k');
assert.equal(new URL(geo.googleEmbedUrl(point,false)).searchParams.get('t'),'m');
assert.deepEqual(source,{x:832591.320,y:820359.389});
console.log(JSON.stringify({land_department_benchmark_matches:true,invalid_xy_rejected:true,google_url_lat_lon_order_verified:true,source_xy_unchanged:true}));
